60917073026,20260917101844,20260917101901', ',')) as v),
     nos_30 as (select unnest(string_to_array('monthly_presence_has_a_chokepoint,credit_ledger_append_only,content_archetypes,topic_bank_and_assignment,insight_watch,rendered_assets_and_libraries,a_diagram_label_is_published_text,render_dedup_and_cost_report,the_collision_window_is_computed_once,a_cte_referenced_once_is_inlined,an_item_knows_why_it_was_chosen,swap_is_a_draw_not_a_generation,a_layout_is_hers_to_change,a_post_can_be_asked_for,a_refused_attempt_still_cost_money,a_paid_batch_survives_a_crash,the_bank_never_holds_a_practitioners_lines,every_paid_call_is_in_the_book,an_eyebrow_is_a_label_not_a_code,the_bank_is_counted_before_it_is_drawn,an_assignment_that_delivered_nothing_is_not_held,a_backup_that_does_not_restore_is_not_a_backup,a_licence_number_is_required_in_every_advertisement,ethics_immediate_negation,a_preflight_can_read_the_quota,a_trigger_function_is_never_a_client_call,a_paid_inclusion_is_not_a_trial,a_stale_subscription_event_does_not_rewrite,revoke_from_public_does_not_revoke_from_anon,the_licence_number_has_one_authority', ',')) as n)
select 'EN PROD, PAS DANS MAIN' as ecart, s.version, s.name,
       case when s.version = any(string_to_array('20260920140000,20260920140100,20260920150000,20260920150100,20260920150200,20260920150300,20260920160000,20260920160100,20260920170000,20260920180000,20260921090000,20260921100000,20260921110000,20260921120000,20260921140000,20260923100000,20260923110000,20260924100000,20260924120000,20260924130000,20260924140000,20260924150000,20260924160000,20260926090000,20260926120000,20260927090000,20260927100000,20260927110000,20260927120000,20260927130000', ',')) then 'UNE DES 30, DÉJÀ APPLIQUÉE sous son propre numéro'
            when s.name in (select n from nos_30) then 'UNE DES 30, DÉJÀ APPLIQUÉE sous un autre numéro'
            when exists (select 1 from nos_30 where s.name ilike '%' || n || '%' or n ilike '%' || s.name || '%') then 'ressemble à une des 30'
            else 'inconnue des dépôts' end as nature
  from supabase_migrations.schema_migrations s where s.version not in (select v from main_v)
union all
select 'DANS MAIN, PAS EN PROD', v, null, null from main_v where v not in (select version from supabase_migrations.schema_migrations)
order by 1, 2;
